import math
from itertools import combinations
from numbers import Real
from statistics import fmean


def exact_partition_report(first, second):
    for name, values in (("first", first), ("second", second)):
        if isinstance(values, (str, bytes)) or not hasattr(values, "__len__") or not hasattr(values, "__iter__"):
            raise TypeError(f"{name} must be a non-string finite sequence")

    left = list(first)
    right = list(second)
    if not left or not right:
        raise ValueError("inputs must be non-empty")
    if len(left) != len(right):
        raise ValueError("inputs must have equal length")
    for value in left + right:
        if isinstance(value, bool) or not isinstance(value, Real):
            raise TypeError("values must be real numbers")
        if not math.isfinite(value):
            raise ValueError("values must be finite")

    observed = fmean(left) - fmean(right)
    combined = left + right
    group_size = len(left)
    all_indices = range(len(combined))
    differences = []
    for chosen in combinations(all_indices, group_size):
        chosen_set = set(chosen)
        group_a = [combined[index] for index in chosen]
        group_b = [combined[index] for index in all_indices if index not in chosen_set]
        differences.append(fmean(group_a) - fmean(group_b))

    threshold = abs(observed)
    extreme_count = sum(abs(value) > threshold for value in differences)
    return {
        "observed": observed,
        "differences": tuple(differences),
        "extreme_fraction": extreme_count / len(differences),
    }

